from dataclasses import dataclass, field
from typing import Dict, List

# Golden / expected schema: column -> type
EXPECTED = {
    "transaction_id": "bigint",
    "user_id": "bigint",
    "amount": "decimal(18,2)",
    "currency": "varchar",
    "event_timestamp": "timestamp",
}
REQUIRED = {"transaction_id", "user_id", "amount", "event_timestamp"}

# Safe widenings: old_type -> set of allowed new types
SAFE_WIDENING = {
    "int": {"bigint", "decimal(18,2)"},
    "bigint": {"decimal(18,2)"},
    "float": {"double"},
}

@dataclass
class DriftReport:
    added: List[str] = field(default_factory=list)
    removed: List[str] = field(default_factory=list)
    type_changed: List[str] = field(default_factory=list)
    breaking: List[str] = field(default_factory=list)

    @property
    def severity(self) -> str:
        return "BREAKING" if self.breaking else ("ADDITIVE" if self.added or self.type_changed else "NONE")

def fetch_observed(conn, schema, table) -> Dict[str, str]:
    rows = conn.execute(
        """SELECT column_name, data_type
           FROM information_schema.columns
           WHERE table_schema = %s AND table_name = %s""",
        (schema, table),
    ).fetchall()
    return {name.lower(): dtype.lower() for name, dtype in rows}

def diff_schema(observed: Dict[str, str]) -> DriftReport:
    r = DriftReport()
    for col in observed:
        if col not in EXPECTED:
            r.added.append(col)  # new column = additive
    for col, exp_type in EXPECTED.items():
        if col not in observed:
            r.removed.append(col)
            if col in REQUIRED:
                r.breaking.append(f"removed required column {col}")
            continue
        obs_type = observed[col]
        if obs_type != exp_type:
            r.type_changed.append(f"{col}: {exp_type} -> {obs_type}")
            if obs_type not in SAFE_WIDENING.get(exp_type, set()):
                r.breaking.append(f"unsafe type change {col}: {exp_type} -> {obs_type}")
    return r

observed = fetch_observed(conn, "staging", "transactions")
report = diff_schema(observed)
print("severity:", report.severity)
if report.severity == "BREAKING":
    raise SystemExit(f"SCHEMA DRIFT (fail-closed): {report.breaking}")
